#include <stdio.h>
#include <string.h>
#include "vr1_export_cmesh.h"

static int vr1_is_ident_char(int c)
{
    if (c >= 'A' && c <= 'Z') return 1;
    if (c >= 'a' && c <= 'z') return 1;
    if (c >= '0' && c <= '9') return 1;
    if (c == '_') return 1;
    return 0;
}

static void vr1_make_symbol(char *out, int cap, const char *in)
{
    int i;
    int j;
    int c;

    if (out == 0 || cap <= 0) return;
    out[0] = '\0';
    if (in == 0 || in[0] == '\0') in = "vr1_scene";
    j = 0;
    c = (unsigned char)in[0];
    if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_')) {
        if (j < cap - 1) out[j++] = '_';
    }
    for (i = 0; in[i] != '\0' && j < cap - 1; i++) {
        c = (unsigned char)in[i];
        out[j++] = (char)(vr1_is_ident_char(c) ? c : '_');
    }
    out[j] = '\0';
}

static int vr1_color_byte(vr1_fx v)
{
    long x;

    if (v < 0) v = 0;
    if (v > VR1_FX_ONE) v = VR1_FX_ONE;
    x = ((long)v * 255L + VR1_FX_HALF) / VR1_FX_ONE;
    if (x < 0) x = 0;
    if (x > 255) x = 255;
    return (int)x;
}

int vr1_export_cmesh(FILE *f, const vr1_scene *s, const char *symbol_name)
{
    char sym[VR1_NAME_MAX];
    char guard[VR1_NAME_MAX + 16];
    long i;
    int mi;

    if (f == 0 || s == 0) return 0;
    vr1_make_symbol(sym, (int)sizeof(sym), symbol_name);
    vr1_make_symbol(guard, (int)sizeof(guard), symbol_name);
    if (guard[0] == '\0') vr1_make_symbol(guard, (int)sizeof(guard), "vr1_scene");

    fprintf(f, "#ifndef %s_CMESH_H\n", guard);
    fprintf(f, "#define %s_CMESH_H\n\n", guard);
    fprintf(f, "/* Generated by vrml1_wrl_c89_codec. Values are fixed-point Q20.12. */\n");
    fprintf(f, "#define %s_VERTEX_COUNT %ldL\n", sym, s->vertex_count);
    fprintf(f, "#define %s_TRIANGLE_COUNT %ldL\n", sym, s->triangle_count);
    fprintf(f, "#define %s_LINE_COUNT %ldL\n", sym, s->line_count);
    fprintf(f, "#define %s_POINT_COUNT %ldL\n", sym, s->point_count);
    fprintf(f, "#define %s_MATERIAL_COUNT %d\n\n", sym, s->material_count);

    fprintf(f, "typedef struct %s_vertex_s { long x; long y; long z; long nx; long ny; long nz; long s; long t; int material; } %s_vertex;\n", sym, sym);
    fprintf(f, "typedef struct %s_triangle_s { long a; long b; long c; int material; } %s_triangle;\n", sym, sym);
    fprintf(f, "typedef struct %s_line_s { long a; long b; int material; } %s_line;\n", sym, sym);
    fprintf(f, "typedef struct %s_point_s { long x; long y; long z; int material; } %s_point;\n", sym, sym);
    fprintf(f, "typedef struct %s_material_s { int r; int g; int b; int alpha; } %s_material;\n\n", sym, sym);

    fprintf(f, "static const %s_material %s_materials[%s_MATERIAL_COUNT] = {\n", sym, sym, sym);
    for (mi = 0; mi < s->material_count; mi++) {
        int r;
        int g;
        int b;
        int a;
        r = vr1_color_byte(s->materials[mi].diffuse.r);
        g = vr1_color_byte(s->materials[mi].diffuse.g);
        b = vr1_color_byte(s->materials[mi].diffuse.b);
        a = 255 - vr1_color_byte(s->materials[mi].transparency);
        fprintf(f, "    { %d, %d, %d, %d }%s\n", r, g, b, a, (mi + 1 < s->material_count) ? "," : "");
    }
    fprintf(f, "};\n\n");

    fprintf(f, "static const %s_vertex %s_vertices[%s_VERTEX_COUNT] = {\n", sym, sym, sym);
    for (i = 0; i < s->vertex_count; i++) {
        const vr1_vertex *v;
        v = &s->vertices[i];
        fprintf(f, "    { %ldL, %ldL, %ldL, %ldL, %ldL, %ldL, %ldL, %ldL, %d }%s\n",
                (long)v->pos.x, (long)v->pos.y, (long)v->pos.z,
                (long)v->normal.x, (long)v->normal.y, (long)v->normal.z,
                (long)v->uv.x, (long)v->uv.y, v->material,
                (i + 1 < s->vertex_count) ? "," : "");
    }
    fprintf(f, "};\n\n");

    fprintf(f, "static const %s_triangle %s_triangles[%s_TRIANGLE_COUNT] = {\n", sym, sym, sym);
    for (i = 0; i < s->triangle_count; i++) {
        fprintf(f, "    { %ldL, %ldL, %ldL, %d }%s\n",
                s->triangles[i].a, s->triangles[i].b, s->triangles[i].c, s->triangles[i].material,
                (i + 1 < s->triangle_count) ? "," : "");
    }
    fprintf(f, "};\n\n");

    fprintf(f, "static const %s_line %s_lines[%s_LINE_COUNT] = {\n", sym, sym, sym);
    for (i = 0; i < s->line_count; i++) {
        fprintf(f, "    { %ldL, %ldL, %d }%s\n",
                s->lines[i].a, s->lines[i].b, s->lines[i].material,
                (i + 1 < s->line_count) ? "," : "");
    }
    fprintf(f, "};\n\n");

    fprintf(f, "static const %s_point %s_points[%s_POINT_COUNT] = {\n", sym, sym, sym);
    for (i = 0; i < s->point_count; i++) {
        fprintf(f, "    { %ldL, %ldL, %ldL, %d }%s\n",
                (long)s->points[i].pos.x, (long)s->points[i].pos.y, (long)s->points[i].pos.z, s->points[i].material,
                (i + 1 < s->point_count) ? "," : "");
    }
    fprintf(f, "};\n\n");

    fprintf(f, "#endif\n");
    return 1;
}
